pragma solidity ^0.8.17;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address newRoundImplementation) public {
        // 1. Allow any address input, including zero
        // 2. Make the caller the owner so onlyOwner passes
        address owner = c.owner();
        vm.prank(owner);
        // The buggy version lacks the require check, so it can set roundImplementation to address(0)
        c.updateRoundImplementation(payable(newRoundImplementation));
        // 3. Assert: roundImplementation should never be the zero address after a successful call
        assertTrue(c.roundImplementation() != address(0));
    }
}

// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.17;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public {
        c = new C();
        // Set up programOperator for create and owner for updateRoundImplementation
        c.initialize();
        // Transfer ownership to this contract so we can call onlyOwner functions
        c.transferOwnership(address(this));
    }

    function testFuzz_property(address newRoundImplementation) public {
        // Bound to avoid precompile collisions but keep wide; allow zero address to trigger bug
        vm.assume(newRoundImplementation != address(0) || newRoundImplementation == address(0));

        bool success;
        try c.updateRoundImplementation(payable(newRoundImplementation)) {
            success = true;
        } catch {
            success = false;
        }

        // After the call, if success, the roundImplementation getter must equal the input argument.
        // The reference reverts for zero address (success=false) and sets correctly for non-zero.
        // The buggy version succeeds for zero address but sets roundImplementation to zero, contradicting the rule.
        assertTrue(!success || c.roundImplementation() == newRoundImplementation, "roundImplementation mismatch");
    }
}

// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.17;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address payable newRoundImplementation) public {
        vm.assume(newRoundImplementation != address(0));
        c.initialize();
        c.updateAlloSettings(address(0x123));
        vm.prank(address(this));
        c.updateRoundImplementation(payable(address(0x456)));
        c.renounceOwnership();
        vm.deal(address(0xB0b), 1 ether);
        vm.startPrank(address(0xB0b));
        bool ok;
        try c.updateRoundImplementation(newRoundImplementation) { ok = true; } catch { ok = false; }
        vm.stopPrank();
        if (ok) {
            assertTrue(c.roundImplementation() != address(0));
        }
    }
}

// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.17;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address newRoundImplementation) public {
        // 1. The owner must be the caller for updateRoundImplementation
        address owner = c.owner();
        vm.prank(owner);
        // 2. Wrap the call in try/catch to detect revert without asserting on it
        bool ok;
        try c.updateRoundImplementation(newRoundImplementation) {
            ok = true;
        } catch {
            ok = false;
        }
        // 3. Rule: if the call did not revert, the returned roundImplementation must equal the argument.
        // The reference reverts on zero address (so ok==false, property vacuously true).
        // The buggy version accepts zero address (ok==true) but then returns address(0) != argument.
        assertTrue(!ok || c.roundImplementation() == newRoundImplementation);
    }
}

